#include <bits/stdc++.h>
using namespace std;

class Solution { public:
 vector<long long> kthPalindrome(vector<int>& queries,int intLength){int half=(intLength+1)/2;long long base=1;for(int i=1;i<half;++i)base*=10;
  vector<long long>ans;for(int q:queries){long long h=base+q-1;if(h>=base*10){ans.push_back(-1);continue;}
   string a=to_string(h),b=a;reverse(b.begin(),b.end());if(intLength%2)b.erase(b.begin());ans.push_back(stoll(a+b));
  }return ans;
 }
};
